package com.powercms.cms.widget;
import com.fasterxml.jackson.databind.*; import com.powercms.cms.audit.AuditService; import com.powercms.cms.widget.entity.*; import com.powercms.cms.widget.repo.*; import com.powercms.common.error.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class WidgetService { private final WidgetDefinitionRepository repo; private final ObjectMapper mapper; private final AuditService audit; public WidgetService(WidgetDefinitionRepository r,ObjectMapper m,AuditService a){repo=r;mapper=m;audit=a;} public record Info(UUID id,UUID siteId,String code,String name,String controllerDefinition,String parameterSchema,String status){}
 public Info save(UUID site,UUID id,String code,String name,String controller,String schema,String actor){if(code==null||!code.matches("[A-Za-z][A-Za-z0-9-]{0,63}"))throw bad("Widget code invalid");JsonNode p=read(schema);if(!p.isObject()||!p.path("properties").isObject()||p.size()>4)throw bad("parameter schema must use properties subset");JsonNode d=read(controller);if(!d.isObject()||!d.has("route")||!d.has("view"))throw bad("Widget controller must be JSON DSL");var w=id==null?new WidgetDefinitionEntity():repo.findById(id).filter(x->site.equals(x.getSiteId())).orElseThrow(()->bad("Widget not found"));if(w.getId()==null)try{var idField=WidgetDefinitionEntity.class.getDeclaredField("id");idField.setAccessible(true);idField.set(w,UUID.randomUUID());}catch(Exception ex){throw bad("Widget id generation failed");} w.setSiteId(site);w.setCode(code);w.setName(name);w.setControllerDefinition(mapperWrite(d));w.setParameterSchema(mapperWrite(p));w.setStatus("DRAFT");w=repo.save(w);audit.write(actor,"WIDGET_SAVE","WIDGET",w.getId().toString(),site,"SUCCESS","JSON DSL only");return info(w);}
 public Info publish(UUID site,UUID id,String actor){var w=require(site,id);w.setStatus("PUBLISHED");w=repo.save(w);audit.write(actor,"WIDGET_PUBLISH","WIDGET",id.toString(),site,"SUCCESS",null);return info(w);} public void delete(UUID site,UUID id,String actor){var w=require(site,id);repo.delete(w);audit.write(actor,"WIDGET_DELETE","WIDGET",id.toString(),site,"SUCCESS",null);} public List<Info> list(UUID site){return repo.findBySiteIdAndStatusOrderByCode(site,"PUBLISHED").stream().map(this::info).toList();} private WidgetDefinitionEntity require(UUID site,UUID id){return repo.findById(id).filter(x->site.equals(x.getSiteId())).orElseThrow(()->bad("Widget not found"));} private Info info(WidgetDefinitionEntity w){return new Info(w.getId(),w.getSiteId(),w.getCode(),w.getName(),w.getControllerDefinition(),w.getParameterSchema(),w.getStatus());} private JsonNode read(String s){try{return mapper.readTree(s);}catch(Exception e){throw bad("JSON definition invalid");}} private String mapperWrite(JsonNode n){try{return mapper.writeValueAsString(n);}catch(Exception e){throw bad("JSON definition invalid");}} private BusinessException bad(String m){return new BusinessException(ErrorCodes.VALIDATION_FAILED,m);} }
